import ast

class SecurityValidator(ast.NodeVisitor):
    FORBIDDEN_MODULES = {"os", "subprocess", "socket", "ctypes", "sys", "pty"}

    def visit_Import(self, node):
        for alias in node.names:
            if alias.name.split(".")[0] in self.FORBIDDEN_MODULES:
                raise SecurityViolation(f"Forbidden module import: {alias.name}")
        self.generic_visit(node)

    def visit_ImportFrom(self, node):
        if node.module and node.module.split(".")[0] in self.FORBIDDEN_MODULES:
            raise SecurityViolation(f"Forbidden module import: {node.module}")
        self.generic_visit(node)

# FastAPI SSE endpoint with stream replay support
@router.get("/submissions/{sub_id}/stream")
async def stream_submission_progress(request: Request, sub_id: str):
    last_event_id = request.headers.get("Last-Event-ID", "0-0")

    async def event_generator():
        current_id = last_event_id
        while True:
            if await request.is_disconnected():
                break
            # Read from stream starting strictly after current_id
            entries = await redis.xread({f"submission:{sub_id}:events": current_id}, count=10, block=2000)
            if entries:
                for stream_name, messages in entries:
                    for msg_id, data in messages:
                        current_id = msg_id
                        yield f"id: {msg_id}\nevent: update\ndata: {json.dumps(data)}\n\n"

    return StreamingResponse(event_generator(), media_type="text/event-stream")
